#!/usr/bin/env python3
"""
seed-modules-25-37.py
Injects modules 25-37 into CPTS Companion seed data files.
Uses triple-quoted strings throughout — no Python string escaping issues.
"""
import json, os

SEED = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'seed')

def load(fn):
    with open(os.path.join(SEED, fn), encoding='utf-8') as f:
        return json.load(f)

def save(fn, data):
    with open(os.path.join(SEED, fn), 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

mods = load('modules-expanded.json')
exs  = load('exercises-expanded.json')
fcs  = load('flashcards-expanded.json')

existing_slugs     = {m['slug']      for m in mods}
existing_prompts   = {e['prompt']    for e in exs}
existing_questions = {fc['question'] for fc in fcs}

# ─── MODULE DEFINITIONS ──────────────────────────────────────────────────────

